{
  "findings": [
    {
      "check_id": "CKV_AWS_25",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 3389",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "Allowing ingress from 0.0.0.0/0 to port 3389 exposes RDP to the entire internet, increasing the risk of brute-force attacks."
    },
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "Lack of description for the security group rule makes it difficult to understand its purpose and manage it effectively."
    }
  ],
  "patched_code": "resource \"aws_security_group_rule\" \"changeme_remote_exec_inline_security_group_rule_incoming_rdp\" {\n  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id\n  type              = \"ingress\"\n  from_port         = 3389\n  to_port           = 3389\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"10.0.0.0/16\"]\n  description       = \"Allow RDP from internal network\"\n}",
  "fix_summary": "Restricted RDP access to a more specific IP range and added a description to the security group rule."
}
